-- Reviewed senior batch 021; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4631,"word":"dogma","meaning":"教條","example":"The discussion questioned a dogma that allowed no room for new evidence.","example_zh":"討論質疑不容納新證據的教條。","original_meaning":"教條","original_example":"Religious dogma.","original_example_zh":"宗教教條。"},{"source_id":4632,"word":"dwindle","meaning":"減少","example":"The pile of unused wood began to dwindle as the model grew.","example_zh":"模型逐漸完成，未用木材也越來越少。","original_meaning":"減少","original_example":"Supplies dwindled.","original_example_zh":"物資日益減少。"},{"source_id":4633,"word":"eccentric","meaning":"古怪的","example":"The eccentric inventor built a clock shaped like a bird.","example_zh":"古怪發明家做出一座鳥形時鐘。","original_meaning":"古怪的","original_example":"An eccentric professor.","original_example_zh":"一位古怪的教授。"},{"source_id":4634,"word":"edify","meaning":"教化；啟迪","example":"The thoughtful lecture could edify listeners of all ages.","example_zh":"深思熟慮的講座能啟迪各年齡聽眾。","original_meaning":"教化","original_example":"Edify the masses.","original_example_zh":"啟迪大眾。"},{"source_id":4635,"word":"elapse","meaning":"流逝","example":"Several minutes would elapse before the glue dried.","example_zh":"膠乾之前，會經過幾分鐘。","original_meaning":"流逝","original_example":"Time elapsed quickly.","original_example_zh":"時間過得很快。"},{"source_id":4636,"word":"elicit","meaning":"引出","example":"The unusual painting could elicit many different interpretations.","example_zh":"不尋常畫作能引出多種不同詮釋。","original_meaning":"引出","original_example":"Elicit a response.","original_example_zh":"引出回應。"},{"source_id":4637,"word":"elucidate","meaning":"闡明","example":"The model helped elucidate the bridge's complicated structure.","example_zh":"模型有助闡明橋梁複雜結構。","original_meaning":"闡明","original_example":"Elucidate the theory.","original_example_zh":"闡明該理論。"},{"source_id":4638,"word":"elusive","meaning":"難以捉摸的","example":"The elusive bird stayed hidden among the reeds.","example_zh":"難以發現的鳥一直藏在蘆葦間。","original_meaning":"難以捉摸的","original_example":"An elusive goal.","original_example_zh":"難以企及的目標。"},{"source_id":4639,"word":"emancipate","meaning":"解放","example":"The exhibit traced the movement to emancipate people from slavery.","example_zh":"展覽追溯使人們擺脫奴隸制度的解放運動。","original_meaning":"解放","original_example":"Emancipate the slaves.","original_example_zh":"解放奴隸。"},{"source_id":4640,"word":"embody","meaning":"體現","example":"The accessible garden could embody the school's commitment to inclusion.","example_zh":"無障礙花園能體現學校對包容的承諾。","original_meaning":"體現","original_example":"Embody the spirit.","original_example_zh":"體現這種精神。"},{"source_id":4641,"word":"enact","meaning":"制定","example":"The council will enact a rule protecting the old trees.","example_zh":"議會將制定保護老樹的規則。","original_meaning":"制定","original_example":"Enact legislation.","original_example_zh":"頒布法律。"},{"source_id":4642,"word":"engender","meaning":"產生","example":"Working together could engender trust between the two groups.","example_zh":"共同工作能在兩組之間產生信任。","original_meaning":"產生","original_example":"Engender trust.","original_example_zh":"建立信任。"},{"source_id":4643,"word":"engross","meaning":"使全神貫注","example":"The intricate puzzle could engross the students for an entire afternoon.","example_zh":"複雜拼圖能讓學生整個下午全神貫注。","original_meaning":"使全神貫注","original_example":"Engrossed in reading.","original_example_zh":"沉浸於閱讀之中。"},{"source_id":4644,"word":"enigma","meaning":"謎","example":"The purpose of the tiny ancient object remained an enigma.","example_zh":"那件微小古物的用途仍是個謎。","original_meaning":"謎","original_example":"A total enigma.","original_example_zh":"完全是個謎。"},{"source_id":4645,"word":"enlighten","meaning":"啟發","example":"The guide hoped to enlighten visitors about the river's history.","example_zh":"導覽員希望讓訪客了解河川歷史。","original_meaning":"啟發","original_example":"Enlighten the public.","original_example_zh":"啟迪大眾。"},{"source_id":4646,"word":"ensue","meaning":"接踵而來","example":"A lively discussion would ensue after the surprising experiment.","example_zh":"出乎意料的實驗後，熱烈討論隨即展開。","original_meaning":"接踵而來","original_example":"Chaos ensued.","original_example_zh":"隨後陷入混亂。"},{"source_id":4647,"word":"entice","meaning":"誘惑；吸引","example":"The colorful book display could entice visitors to explore the library.","example_zh":"繽紛書展能吸引訪客探索圖書館。","original_meaning":"誘惑","original_example":"Entice customers.","original_example_zh":"吸引顧客。"},{"source_id":4648,"word":"entrench","meaning":"使根深蒂固","example":"The old seating plan helped entrench divisions between the clubs.","example_zh":"舊座位安排使社團間的分隔更加根深蒂固。","original_meaning":"根深蒂固","original_example":"Entrenched beliefs.","original_example_zh":"根深蒂固的信念。"},{"source_id":4649,"word":"enumerate","meaning":"列舉","example":"The teacher asked us to enumerate the materials needed for the model.","example_zh":"老師請我們列舉模型所需材料。","original_meaning":"列舉","original_example":"Enumerate the reasons.","original_example_zh":"列舉原因。"},{"source_id":4650,"word":"epoch","meaning":"紀元","example":"The arrival of the railway marked a new epoch in the town's history.","example_zh":"鐵路到來，開啟城鎮歷史的新紀元。","original_meaning":"紀元","original_example":"A new epoch.","original_example_zh":"一個新時代。"},{"source_id":4651,"word":"equitable","meaning":"公平的","example":"The equitable plan gave every group equal access to the tools.","example_zh":"公平計畫讓每組都能平等使用工具。","original_meaning":"公平的","original_example":"An equitable solution.","original_example_zh":"一個公平的解決方案。"},{"source_id":4652,"word":"erudite","meaning":"博學的","example":"The erudite historian answered questions about many different periods.","example_zh":"博學歷史學家回答關於不同時期的問題。","original_meaning":"博學的","original_example":"An erudite professor.","original_example_zh":"學識淵博的教授。"},{"source_id":4653,"word":"espouse","meaning":"支持","example":"The club chose to espouse the principle of open discussion.","example_zh":"社團選擇支持公開討論的原則。","original_meaning":"支持","original_example":"Espouse a cause.","original_example_zh":"支持某項事業。"},{"source_id":4654,"word":"esteem","meaning":"尊敬","example":"The community held the retired teacher in high esteem.","example_zh":"社區對退休老師十分尊敬。","original_meaning":"尊敬","original_example":"Hold in high esteem.","original_example_zh":"十分敬重。"},{"source_id":4655,"word":"euphoria","meaning":"欣喜若狂","example":"The team's victory filled the students with euphoria.","example_zh":"隊伍勝利讓學生欣喜若狂。","original_meaning":"欣喜若狂","original_example":"A sense of euphoria.","original_example_zh":"一種欣喜若狂的感覺。"},{"source_id":4656,"word":"exalt","meaning":"頌揚","example":"The poem sought to exalt the quiet courage of ordinary helpers.","example_zh":"詩作試圖頌揚平凡助人者的沉靜勇氣。","original_meaning":"頌揚","original_example":"Exalt the hero.","original_example_zh":"頌揚英雄。"},{"source_id":4657,"word":"excavate","meaning":"挖掘","example":"The archaeologists began to excavate the buried wall carefully.","example_zh":"考古學家開始小心挖掘埋藏牆面。","original_meaning":"挖掘","original_example":"Excavate the site.","original_example_zh":"挖掘該遺址。"},{"source_id":4658,"word":"exemplary","meaning":"模範的","example":"Her exemplary care of the tools set a standard for the group.","example_zh":"她模範般愛護工具，為小組樹立標準。","original_meaning":"模範的","original_example":"Exemplary behavior.","original_example_zh":"堪稱典範的行為。"},{"source_id":4659,"word":"exhort","meaning":"勸告","example":"The coach will exhort the team to keep practicing patiently.","example_zh":"教練將勸勉隊員耐心繼續練習。","original_meaning":"勸告","original_example":"Exhort to action.","original_example_zh":"敦促採取行動。"},{"source_id":4660,"word":"expedite","meaning":"加速","example":"The new sorting system helped expedite the library's work.","example_zh":"新的分類系統加快圖書館工作。","original_meaning":"加速","original_example":"Expedite the process.","original_example_zh":"加快處理進度。"},{"source_id":4661,"word":"exquisite","meaning":"精緻的","example":"The exquisite carving showed tiny leaves and birds.","example_zh":"精緻雕刻呈現微小葉片與鳥。","original_meaning":"精緻的","original_example":"Exquisite craftsmanship.","original_example_zh":"精湛的工藝。"},{"source_id":4662,"word":"extol","meaning":"頌揚","example":"The speaker began to extol the volunteers' generosity.","example_zh":"講者開始頌揚志工慷慨。","original_meaning":"頌揚","original_example":"Extol the virtues.","original_example_zh":"讚揚美德。"},{"source_id":4663,"word":"extravagant","meaning":"奢侈的","example":"The extravagant celebration used far more decorations than necessary.","example_zh":"奢侈慶典使用遠超需要的裝飾。","original_meaning":"奢侈的","original_example":"An extravagant lifestyle.","original_example_zh":"奢侈的生活方式。"},{"source_id":4664,"word":"exuberant","meaning":"充沛的","example":"The exuberant musicians greeted the audience with bright smiles.","example_zh":"熱情洋溢的樂手以燦爛笑容迎接觀眾。","original_meaning":"充沛的","original_example":"Exuberant energy.","original_example_zh":"充沛的活力。"},{"source_id":4665,"word":"facile","meaning":"輕率的","example":"The facile answer ignored the real difficulty of repairing the bridge.","example_zh":"輕率答案忽略修橋真正的困難。","original_meaning":"輕率的","original_example":"A facile argument.","original_example_zh":"膚淺的論點。"},{"source_id":4666,"word":"fanatical","meaning":"狂熱的","example":"The fanatical collector searched every shop for the missing chess piece.","example_zh":"狂熱收藏者走遍商店尋找缺少的棋子。","original_meaning":"狂熱的","original_example":"Fanatical devotion.","original_example_zh":"狂熱的奉獻。"},{"source_id":4667,"word":"fastidious","meaning":"挑剔的；一絲不苟的","example":"The fastidious restorer checked every tiny mark on the painting.","example_zh":"挑剔細心的修復師檢查畫作每一道微小痕跡。","original_meaning":"挑剔的","original_example":"A fastidious dresser.","original_example_zh":"一位講究穿著的人。"},{"source_id":4668,"word":"fervent","meaning":"熱烈的","example":"Her fervent support helped keep the garden project alive.","example_zh":"她熱烈支持，幫助花園計畫持續進行。","original_meaning":"熱烈的","original_example":"A fervent prayer.","original_example_zh":"一聲虔誠的祈禱。"},{"source_id":4669,"word":"fickle","meaning":"善變的","example":"The fickle character changed his favorite design several times.","example_zh":"善變角色數度改變最喜歡的設計。","original_meaning":"善變的","original_example":"A fickle friend.","original_example_zh":"一個善變的朋友。"},{"source_id":4670,"word":"fledgling","meaning":"新生的","example":"The fledgling orchestra practiced its first complete piece.","example_zh":"新成立的管弦樂團排練第一首完整樂曲。","original_meaning":"新生的","original_example":"A fledgling company.","original_example_zh":"一家新創公司。"},{"source_id":4671,"word":"fleeting","meaning":"短暫的","example":"A fleeting rainbow appeared above the waterfall.","example_zh":"一道短暫彩虹出現在瀑布上方。","original_meaning":"短暫的","original_example":"A fleeting moment.","original_example_zh":"轉瞬即逝的時刻。"},{"source_id":4672,"word":"flimsy","meaning":"脆弱的","example":"The flimsy cardboard tower bent under the small weight.","example_zh":"脆弱紙板塔在小砝碼下彎曲。","original_meaning":"脆弱的","original_example":"A flimsy excuse.","original_example_zh":"牽強的藉口。"},{"source_id":4673,"word":"foment","meaning":"煽動","example":"The false rumor began to foment distrust within the fictional council.","example_zh":"虛構議會裡，不實謠言開始煽起不信任。","original_meaning":"煽動","original_example":"Foment rebellion.","original_example_zh":"煽動叛亂。"},{"source_id":4674,"word":"forsake","meaning":"拋棄","example":"The friends promised not to forsake one another during difficulties.","example_zh":"朋友承諾在困難中不拋棄彼此。","original_meaning":"拋棄","original_example":"Forsake old habits.","original_example_zh":"摒棄舊習慣。"},{"source_id":4675,"word":"forthright","meaning":"直率的","example":"Her forthright explanation made the problem clear.","example_zh":"她直率的說明讓問題清楚明白。","original_meaning":"直率的","original_example":"A forthright answer.","original_example_zh":"一個直率的回答。"},{"source_id":4676,"word":"frantic","meaning":"瘋狂的；焦急慌亂的","example":"The frantic search for the missing score ended just before rehearsal.","example_zh":"排練前，焦急尋找失蹤樂譜的行動終於結束。","original_meaning":"瘋狂的","original_example":"Frantic efforts.","original_example_zh":"拼命的努力。"},{"source_id":4677,"word":"frivolity","meaning":"輕浮；輕鬆玩樂","example":"The brief game added a little frivolity to the serious meeting.","example_zh":"短遊戲為嚴肅會議添一點輕鬆玩樂。","original_meaning":"輕浮","original_example":"A time for frivolity.","original_example_zh":"放縱的時刻。"},{"source_id":4678,"word":"frugality","meaning":"節儉","example":"The club's frugality allowed it to buy more books.","example_zh":"社團節儉，因此能購買更多書。","original_meaning":"節儉","original_example":"Practice frugality.","original_example_zh":"實踐節儉。"},{"source_id":4679,"word":"fulfillment","meaning":"成就感","example":"Completing the garden brought a deep sense of fulfillment.","example_zh":"完成花園帶來深刻成就感。","original_meaning":"成就感","original_example":"A sense of fulfillment.","original_example_zh":"一種成就感。"},{"source_id":4680,"word":"garner","meaning":"收集","example":"The science project began to garner support from the community.","example_zh":"科學專案開始獲得社區支持。","original_meaning":"收集","original_example":"Garner support.","original_example_zh":"爭取支持。"},{"source_id":4681,"word":"genial","meaning":"親切的","example":"The genial librarian welcomed every question.","example_zh":"親切圖書館員歡迎每個問題。","original_meaning":"親切的","original_example":"A genial host.","original_example_zh":"一位和藹可親的主人。"},{"source_id":4682,"word":"glaring","meaning":"明顯的","example":"The drawing contained a glaring error in the bridge's support.","example_zh":"圖面裡的橋梁支撐有一個明顯錯誤。","original_meaning":"明顯的","original_example":"A glaring error.","original_example_zh":"一個明顯的錯誤。"},{"source_id":4683,"word":"gloomy","meaning":"陰暗的","example":"The gloomy corridor brightened when the windows were cleaned.","example_zh":"原本陰暗的走廊在窗戶清潔後變明亮。","original_meaning":"陰暗的","original_example":"A gloomy forecast.","original_example_zh":"陰鬱的預測。"},{"source_id":4684,"word":"gracious","meaning":"優雅的；親切有禮的","example":"The gracious host thanked every volunteer personally.","example_zh":"有禮親切的主人親自感謝每位志工。","original_meaning":"優雅的","original_example":"A gracious host.","original_example_zh":"一位親切的主人。"},{"source_id":4685,"word":"grandiose","meaning":"宏偉的；浮誇的","example":"The grandiose plan called for a palace far larger than the village needed.","example_zh":"宏大浮誇計畫要求興建遠超村莊需要的宮殿。","original_meaning":"宏偉的","original_example":"A grandiose plan.","original_example_zh":"一個宏偉的計劃。"},{"source_id":4686,"word":"gratify","meaning":"使滿足","example":"Seeing the seedlings thrive could gratify the whole team.","example_zh":"看幼苗茁壯，能讓全隊感到滿足。","original_meaning":"使滿足","original_example":"Gratified by the result.","original_example_zh":"對結果感到滿意。"},{"source_id":4687,"word":"gregarious","meaning":"合群的","example":"The gregarious student quickly made friends at the workshop.","example_zh":"合群學生在工作坊很快交到朋友。","original_meaning":"合群的","original_example":"A gregarious person.","original_example_zh":"一個愛社交的人。"},{"source_id":4688,"word":"grievous","meaning":"極嚴重的","example":"The storm caused grievous damage to the old orchard.","example_zh":"風暴嚴重損壞老果園。","original_meaning":"極嚴重的","original_example":"A grievous error.","original_example_zh":"一個嚴重的錯誤。"},{"source_id":4689,"word":"gruesome","meaning":"恐怖的","example":"The actor wore a gruesome monster mask for the school play.","example_zh":"演員為校園戲劇戴上恐怖怪獸面具。","original_meaning":"恐怖的","original_example":"A gruesome scene.","original_example_zh":"慘不忍睹的景象。"},{"source_id":4690,"word":"gullible","meaning":"容易受騙的","example":"The gullible character believed the obviously impossible claim.","example_zh":"容易受騙的角色相信顯然不可能的說法。","original_meaning":"容易受騙的","original_example":"A gullible person.","original_example_zh":"一個輕信的人。"},{"source_id":4691,"word":"habitual","meaning":"慣常的","example":"Her habitual morning walk took her past the school garden.","example_zh":"她慣常的晨間散步會經過校園花園。","original_meaning":"慣常的","original_example":"A habitual liar.","original_example_zh":"一個慣於說謊的人。"},{"source_id":4692,"word":"hamstring","meaning":"阻撓","example":"A shortage of materials could hamstring the restoration project.","example_zh":"材料短缺可能阻撓修復專案。","original_meaning":"阻撓","original_example":"Hamstrung by regulations.","original_example_zh":"受制於法規。"},{"source_id":4693,"word":"harbinger","meaning":"預兆","example":"The first blossoms were a harbinger of spring.","example_zh":"最初花朵是春天將至的預兆。","original_meaning":"預兆","original_example":"A harbinger of spring.","original_example_zh":"春天的先兆。"},{"source_id":4694,"word":"harmonious","meaning":"和諧的","example":"The harmonious arrangement of trees and paths made the garden peaceful.","example_zh":"樹木與步道和諧配置，讓花園寧靜。","original_meaning":"和諧的","original_example":"A harmonious blend.","original_example_zh":"和諧的融合。"},{"source_id":4695,"word":"haughty","meaning":"傲慢的","example":"The haughty character refused to listen to the beginners.","example_zh":"傲慢角色拒絕聆聽新手。","original_meaning":"傲慢的","original_example":"A haughty attitude.","original_example_zh":"傲慢的態度。"},{"source_id":4696,"word":"hectic","meaning":"繁忙的","example":"The hectic morning involved deliveries, rehearsals, and a final inspection.","example_zh":"忙碌早晨包括收貨、排練與最後檢查。","original_meaning":"繁忙的","original_example":"A hectic schedule.","original_example_zh":"忙碌的行程。"},{"source_id":4697,"word":"hefty","meaning":"大量的；沉重的","example":"The volunteers carried a hefty box of donated books together.","example_zh":"志工一起搬一大箱捐贈書籍。","original_meaning":"大量的","original_example":"A hefty fine.","original_example_zh":"一筆巨額罰款。"},{"source_id":4698,"word":"hoard","meaning":"囤積","example":"The story warned against the urge to hoard supplies while others went without.","example_zh":"故事告誡不要在別人缺乏物資時囤積用品。","original_meaning":"囤積","original_example":"Hoard supplies.","original_example_zh":"囤積物資。"},{"source_id":4699,"word":"idyllic","meaning":"田園般的","example":"The idyllic village lay beside a clear stream.","example_zh":"田園般村莊坐落清澈溪流旁。","original_meaning":"田園般的","original_example":"An idyllic village.","original_example_zh":"一個田園詩般的村莊。"},{"source_id":4700,"word":"illicit","meaning":"非法的","example":"The museum investigated the illicit sale of a stolen artifact.","example_zh":"博物館調查被盜文物的非法交易。","original_meaning":"非法的","original_example":"Illicit activities.","original_example_zh":"違禁活動。"},{"source_id":4701,"word":"immaculate","meaning":"完美的；潔淨無瑕的","example":"The immaculate workshop had every tool in its place.","example_zh":"一塵不染工坊中，每件工具都在固定位置。","original_meaning":"完美的","original_example":"An immaculate record.","original_example_zh":"無瑕的紀錄。"},{"source_id":4702,"word":"imminent","meaning":"迫在眉睫的","example":"The dark clouds suggested that rain was imminent.","example_zh":"烏雲顯示雨就要來了。","original_meaning":"迫在眉睫的","original_example":"Imminent danger.","original_example_zh":"迫在眉睫的危險。"},{"source_id":4703,"word":"impede","meaning":"阻礙","example":"The fallen branch could impede access to the garden.","example_zh":"倒枝可能阻礙進入花園。","original_meaning":"阻礙","original_example":"Impede traffic.","original_example_zh":"阻礙交通。"},{"source_id":4704,"word":"implicate","meaning":"牽連","example":"The new documents could implicate another official in the scandal.","example_zh":"新文件可能牽連另一位官員涉入醜聞。","original_meaning":"牽連","original_example":"Implicated in the scandal.","original_example_zh":"捲入醜聞。"},{"source_id":4705,"word":"impoverished","meaning":"貧困的","example":"The charity supplied books to schools in impoverished communities.","example_zh":"慈善團體供書給貧困社區學校。","original_meaning":"貧困的","original_example":"An impoverished nation.","original_example_zh":"一個貧困的國家。"},{"source_id":4706,"word":"improvise","meaning":"即興","example":"The musicians began to improvise a melody during rehearsal.","example_zh":"樂手在排練時開始即興演奏旋律。","original_meaning":"即興","original_example":"Improvise a solution.","original_example_zh":"即興想出一個解決方案。"},{"source_id":4707,"word":"incisive","meaning":"敏銳的","example":"Her incisive questions revealed a weakness in the design.","example_zh":"她敏銳提問揭露設計弱點。","original_meaning":"敏銳的","original_example":"An incisive analysis.","original_example_zh":"一項犀利的分析。"},{"source_id":4708,"word":"incline","meaning":"傾向","example":"The evidence may incline the team to choose the simpler design.","example_zh":"證據可能使團隊傾向選較簡單設計。","original_meaning":"傾向","original_example":"Inclined to agree.","original_example_zh":"傾向於同意。"},{"source_id":4709,"word":"incoherent","meaning":"語無倫次的","example":"The hurried explanation was incoherent until the speaker organized his ideas.","example_zh":"匆忙說明原本語無倫次，直到講者整理好想法。","original_meaning":"語無倫次的","original_example":"An incoherent speech.","original_example_zh":"一篇語無倫次的演說。"},{"source_id":4710,"word":"incriminate","meaning":"指控","example":"The missing painting's location could incriminate the dishonest dealer.","example_zh":"失竊畫作的所在位置可能成為指控不誠實商人的證據。","original_meaning":"指控","original_example":"Incriminating evidence.","original_example_zh":"罪證。"},{"source_id":4711,"word":"indebted","meaning":"感恩的","example":"We felt indebted to the volunteers who restored the library.","example_zh":"我們感激修復圖書館的志工。","original_meaning":"感恩的","original_example":"Indebted to you.","original_example_zh":"感激不盡。"},{"source_id":4712,"word":"indictment","meaning":"起訴書","example":"The court received an indictment setting out the formal charges.","example_zh":"法院收到列明正式指控的起訴書。","original_meaning":"起訴書","original_example":"A federal indictment.","original_example_zh":"聯邦起訴書。"},{"source_id":4713,"word":"indulge","meaning":"放縱；盡情享受","example":"She decided to indulge in a quiet afternoon of reading.","example_zh":"她決定讓自己享受一個安靜閱讀的午後。","original_meaning":"放縱","original_example":"Indulge in luxury.","original_example_zh":"沉溺於奢華。"},{"source_id":4714,"word":"inept","meaning":"無能的；笨拙的","example":"The character's inept attempt to repair the clock made the problem worse.","example_zh":"角色笨拙修鐘的嘗試，讓問題更糟。","original_meaning":"無能的","original_example":"An inept leader.","original_example_zh":"一位無能的領導者。"},{"source_id":4715,"word":"inert","meaning":"惰性的","example":"The chemistry lesson compared inert materials with more reactive ones.","example_zh":"化學課比較惰性材料與較活潑材料。","original_meaning":"惰性的","original_example":"An inert gas.","original_example_zh":"惰性氣體。"},{"source_id":4716,"word":"infatuated","meaning":"迷戀的","example":"The student was infatuated with the idea of becoming an astronaut.","example_zh":"那位學生對成為太空人的想法十分著迷。","original_meaning":"迷戀的","original_example":"Infatuated with her.","original_example_zh":"對她一見鍾情。"},{"source_id":4717,"word":"inflame","meaning":"激怒；激化","example":"The false accusation began to inflame the argument.","example_zh":"不實指控開始激化爭論。","original_meaning":"激怒","original_example":"Inflame tensions.","original_example_zh":"激化緊張局勢。"},{"source_id":4718,"word":"ingenuity","meaning":"創造力","example":"The student's ingenuity turned spare parts into a useful watering device.","example_zh":"學生的創造力把備用零件變成實用澆水裝置。","original_meaning":"創造力","original_example":"Show ingenuity.","original_example_zh":"展現巧思。"},{"source_id":4719,"word":"innocuous","meaning":"無害的","example":"The mysterious object proved to be an innocuous old button.","example_zh":"神祕物件證實只是一顆無害老鈕扣。","original_meaning":"無害的","original_example":"An innocuous remark.","original_example_zh":"一句無傷大雅的評論。"},{"source_id":4720,"word":"insatiable","meaning":"貪得無厭的；無法滿足的","example":"Her insatiable curiosity led her to ask another thoughtful question.","example_zh":"她無盡好奇心使她又提出深思問題。","original_meaning":"貪得無厭的","original_example":"An insatiable appetite.","original_example_zh":"永不滿足的慾望。"},{"source_id":4721,"word":"insidious","meaning":"陰險的；暗中有害的","example":"The insidious leak slowly damaged the books before anyone noticed.","example_zh":"隱蔽漏水在被發現前已慢慢損壞書籍。","original_meaning":"陰險的","original_example":"An insidious threat.","original_example_zh":"一種隱蔽的威脅。"},{"source_id":4722,"word":"insinuate","meaning":"暗示","example":"The speaker seemed to insinuate that the design had been copied.","example_zh":"講者似乎暗示那個設計是抄來的。","original_meaning":"暗示","original_example":"What are you insinuating?","original_example_zh":"你暗示什麼？"},{"source_id":4723,"word":"instigate","meaning":"煽動","example":"The novel's dishonest adviser tried to instigate a quarrel.","example_zh":"小說中不誠實顧問試圖挑起爭吵。","original_meaning":"煽動","original_example":"Instigate conflict.","original_example_zh":"煽動衝突。"},{"source_id":4724,"word":"insurmountable","meaning":"無法克服的","example":"The huge task seemed insurmountable until we divided it into smaller steps.","example_zh":"龐大任務原本看似無法克服，直到我們拆成小步驟。","original_meaning":"無法克服的","original_example":"Insurmountable obstacles.","original_example_zh":"無法克服的障礙。"},{"source_id":4725,"word":"intangible","meaning":"無形的","example":"The project gave us intangible benefits such as trust and confidence.","example_zh":"專案帶來信任與信心等無形益處。","original_meaning":"無形的","original_example":"Intangible assets.","original_example_zh":"無形資產。"},{"source_id":4726,"word":"irate","meaning":"憤怒的","example":"The irate visitor calmed down after the staff explained the delay.","example_zh":"憤怒訪客在工作人員說明延誤後平靜下來。","original_meaning":"憤怒的","original_example":"An irate customer.","original_example_zh":"一位憤怒的顧客。"},{"source_id":4727,"word":"irreversible","meaning":"不可逆的","example":"Baking the clay caused an irreversible change.","example_zh":"陶土燒製後產生不可逆變化。","original_meaning":"不可逆的","original_example":"Irreversible damage.","original_example_zh":"不可逆的損害。"},{"source_id":4728,"word":"juxtapose","meaning":"並列","example":"The exhibition will juxtapose the old bridge with a model of its replacement.","example_zh":"展覽將並列老橋與新橋替代方案模型。","original_meaning":"並列","original_example":"Juxtapose two ideas.","original_example_zh":"將兩個想法並列。"},{"source_id":4729,"word":"kinship","meaning":"親屬關係","example":"The family photographs revealed a strong sense of kinship.","example_zh":"家族照片流露深厚親屬情誼。","original_meaning":"親屬關係","original_example":"A sense of kinship.","original_example_zh":"親情。"},{"source_id":4730,"word":"laden","meaning":"裝滿的","example":"The cart was laden with books for the village library.","example_zh":"推車裝滿送往村莊圖書館的書。","original_meaning":"裝滿的","original_example":"Laden with goods.","original_example_zh":"裝載著貨物。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-dogma-01-v1","level":"senior","word":"dogma","sort_order":1,"sense":"教條","alt_zh":"成年教師與高中生比較古老書籍觀點和新科學模型，鼓勵理性討論，無嘲弄宗教。","example":"The discussion questioned a dogma that allowed no room for new evidence.","example_zh":"討論質疑不容納新證據的教條。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dogma-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dwindle-01-v1","level":"senior","word":"dwindle","sort_order":1,"sense":"減少","alt_zh":"高中團隊在成年老師旁組裝逐漸完整的模型屋，旁邊木棒堆已變小。","example":"The pile of unused wood began to dwindle as the model grew.","example_zh":"模型逐漸完成，未用木材也越來越少。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dwindle-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-eccentric-01-v1","level":"senior","word":"eccentric","sort_order":1,"sense":"古怪的","alt_zh":"友善成年發明家在充滿創意的工坊展示奇特木鳥時鐘，高中訪客好奇觀看。","example":"The eccentric inventor built a clock shaped like a bird.","example_zh":"古怪發明家做出一座鳥形時鐘。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/eccentric-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-edify-01-v1","level":"senior","word":"edify","sort_order":1,"sense":"教化；啟迪","alt_zh":"成年講者在社區圖書館用科學模型啟發不同年齡聽眾，高中生專注聆聽。","example":"The thoughtful lecture could edify listeners of all ages.","example_zh":"深思熟慮的講座能啟迪各年齡聽眾。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/edify-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elapse-01-v1","level":"senior","word":"elapse","sort_order":1,"sense":"流逝","alt_zh":"高中生與成年老師等待安全水性白膠固定模型，桌上有小沙漏。","example":"Several minutes would elapse before the glue dried.","example_zh":"膠乾之前，會經過幾分鐘。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elapse-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elicit-01-v1","level":"senior","word":"elicit","sort_order":1,"sense":"引出","alt_zh":"高中生在成年美術老師引導下，圍著抽象畫各自提出想法。","example":"The unusual painting could elicit many different interpretations.","example_zh":"不尋常畫作能引出多種不同詮釋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elicit-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elucidate-01-v1","level":"senior","word":"elucidate","sort_order":1,"sense":"闡明","alt_zh":"成年工程師向高中生展示透明橋梁剖面模型，指向清楚梁柱與支架。","example":"The model helped elucidate the bridge's complicated structure.","example_zh":"模型有助闡明橋梁複雜結構。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elucidate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elusive-01-v1","level":"senior","word":"elusive","sort_order":1,"sense":"難以捉摸的","alt_zh":"成年自然嚮導與高中觀鳥隊從安全小屋遠距尋找蘆葦叢中僅露部分身影的鳥。","example":"The elusive bird stayed hidden among the reeds.","example_zh":"難以發現的鳥一直藏在蘆葦間。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elusive-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-emancipate-01-v1","level":"senior","word":"emancipate","sort_order":1,"sense":"解放","alt_zh":"高中生在歷史博物館看打開的舊枷鎖文物與走向自由的成年人物畫作，無受虐。","example":"The exhibit traced the movement to emancipate people from slavery.","example_zh":"展覽追溯使人們擺脫奴隸制度的解放運動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/emancipate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-embody-01-v1","level":"senior","word":"embody","sort_order":1,"sense":"體現","alt_zh":"不同能力高中生與成年老師平等使用寬敞平緩花園步道與合適高度桌面。","example":"The accessible garden could embody the school's commitment to inclusion.","example_zh":"無障礙花園能體現學校對包容的承諾。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/embody-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-enact-01-v1","level":"senior","word":"enact","sort_order":1,"sense":"制定","alt_zh":"虛構成年市議員正式舉手表決，桌上有古樹公園模型，無文字或黨徽。","example":"The council will enact a rule protecting the old trees.","example_zh":"議會將制定保護老樹的規則。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/enact-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-engender-01-v1","level":"senior","word":"engender","sort_order":1,"sense":"產生","alt_zh":"兩組高中社團在成年老師旁合作修理木椅，逐漸微笑互相協助。","example":"Working together could engender trust between the two groups.","example_zh":"共同工作能在兩組之間產生信任。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/engender-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-engross-01-v1","level":"senior","word":"engross","sort_order":1,"sense":"使全神貫注","alt_zh":"高中生在明亮教室專注一起拼立體木製幾何模型，無干擾。","example":"The intricate puzzle could engross the students for an entire afternoon.","example_zh":"複雜拼圖能讓學生整個下午全神貫注。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/engross-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-enigma-01-v1","level":"senior","word":"enigma","sort_order":1,"sense":"謎","alt_zh":"成年考古學家與高中生在博物館桌邊以放大鏡好奇查看不明古代小器物。","example":"The purpose of the tiny ancient object remained an enigma.","example_zh":"那件微小古物的用途仍是個謎。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/enigma-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-enlighten-01-v1","level":"senior","word":"enlighten","sort_order":1,"sense":"啟發","alt_zh":"成年導覽員向高中生展示河川歷史照片、古橋模型與舊航海工具。","example":"The guide hoped to enlighten visitors about the river's history.","example_zh":"導覽員希望讓訪客了解河川歷史。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/enlighten-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ensue-01-v1","level":"senior","word":"ensue","sort_order":1,"sense":"接踵而來","alt_zh":"高中生與成年老師完成安全水輪模型示範後，興奮圍桌討論結果。","example":"A lively discussion would ensue after the surprising experiment.","example_zh":"出乎意料的實驗後，熱烈討論隨即展開。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ensue-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-entice-01-v1","level":"senior","word":"entice","sort_order":1,"sense":"誘惑；吸引","alt_zh":"高中生被明亮圖書館入口彩色插畫書籍吸引，成年館員友善迎接。","example":"The colorful book display could entice visitors to explore the library.","example_zh":"繽紛書展能吸引訪客探索圖書館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/entice-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-entrench-01-v1","level":"senior","word":"entrench","sort_order":1,"sense":"使根深蒂固","alt_zh":"兩組高中社團長期分坐教室兩端，成年老師準備重新安排圓桌促進交流。","example":"The old seating plan helped entrench divisions between the clubs.","example_zh":"舊座位安排使社團間的分隔更加根深蒂固。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/entrench-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-enumerate-01-v1","level":"senior","word":"enumerate","sort_order":1,"sens